import sys

def find(x):
    if parent[x] != x:
        parent[x] = find(parent[x])
    return parent[x]

def union(x, y):
    rootX = find(x)
    rootY = find(y)
    if rootX != rootY:
        parent[rootY] = rootX

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    managers = list(map(int, data[1:]))

    global parent
    parent = list(range(n + 1))

    for i in range(1, n + 1):
        if managers[i - 1] != -1:
            union(i, managers[i - 1])

    groups = set(find(i) for i in range(1, n + 1))
    print(len(groups))

if __name__ == "__main__":
    main()
